205	  private void maybeSleep() throws InterruptedException, IOException {
206	    if (testWasThrottled) {
207	      LOG.info("Sleeping briefly to let store recover");
208	      Thread.sleep(30_000);
209	      getFileSystem().delete(path("recovery"), true);
210	      testWasThrottled = false;
211	    }
212	  }
