307	  private List<DeleteObjectsRequest.KeyVersion> buildDeleteRequest(
308	      String base, int count) {
309	    List<DeleteObjectsRequest.KeyVersion> request = new ArrayList<>(count);
310	    for (int i = 0; i < count; i++) {
311	      request.add(new DeleteObjectsRequest.KeyVersion(
312	          String.format("%s/file-%04d", base, i)));
313	    }
314	    return request;
315	  }
